package com.loja.service;

import com.loja.model.*;
import com.loja.repository.*;
import com.loja.strategy.*;
import com.loja.util.Money;
import java.time.Instant;
import java.util.*;

public class OrderService {
    private final ProductRepository productRepo;
    private final OrderRepository orderRepo;
    private final CustomerRepository customerRepo;
    private final NotificationRepository notificationRepo;
    private final CheckoutService checkoutService;
    private final Map<String, String> paymentTracking = new HashMap<>();

    public OrderService(ProductRepository productRepo, OrderRepository orderRepo,
                       CustomerRepository customerRepo, NotificationRepository notificationRepo) {
        this.productRepo = productRepo;
        this.orderRepo = orderRepo;
        this.customerRepo = customerRepo;
        this.notificationRepo = notificationRepo;
        this.checkoutService = new CheckoutService(productRepo, this);
    }

    public Order createOrder(CheckoutRequest request) throws CheckoutException {
        OrderSummary summary = checkoutService.calculateSummary(request);

        String orderId = generateOrderId();
        Order order = new Order(
            orderId,
            request.customer.cpf,
            request.customer.email,
            OrderStatus.AWAITING_PAYMENT,
            Instant.now(),
            summary,
            new ArrayList<>(request.items)
        );

        orderRepo.create(order);

        Customer customer = customerRepo.findByCpf(request.customer.cpf);
        if (customer == null) {
            customerRepo.createOrUpdate(request.customer.cpf, 0.0);
        }

        return order;
    }

    public Order processPayment(String orderId, String transactionId, String paidAtStr) throws OrderException {
        Order order = orderRepo.findById(orderId);
        if (order == null) {
            throw new OrderException("ORDER_NOT_FOUND", 404);
        }

        if (transactionId == null || paidAtStr == null) {
            throw new OrderException("INVALID_ORDER", 422);
        }

        if (order.status != OrderStatus.AWAITING_PAYMENT) {
            throw new OrderException("OPERATION_NOT_ALLOWED", 409);
        }

        synchronized (paymentTracking) {
            String key = orderId + ":" + transactionId;
            if (paymentTracking.containsKey(key)) {
                return order;
            }
            paymentTracking.put(key, "processed");
        }

        Instant paidAt = Instant.parse(paidAtStr);
        Instant expiryTime = order.createdAt.plusSeconds(48 * 3600);

        if (paidAt.isAfter(expiryTime)) {
            orderRepo.updateStatus(orderId, OrderStatus.CANCELLED);
            Notification notification = new Notification(
                generateNotificationId(),
                NotificationType.ORDER_CANCELLED,
                orderId,
                order.cpf,
                NotificationStatus.NEW
            );
            notificationRepo.create(notification);
            throw new OrderException("ORDER_EXPIRED", 409);
        }

        validateStockAvailability(order);

        orderRepo.updateStatusAndPaidAt(orderId, OrderStatus.PAID, paidAt);

        deductStock(order);

        addCustomerCredit(order);

        Notification notification = new Notification(
            generateNotificationId(),
            NotificationType.PAYMENT_APPROVED,
            orderId,
            order.cpf,
            NotificationStatus.NEW
        );
        notificationRepo.create(notification);

        order.status = OrderStatus.PAID;
        order.paidAt = paidAt;
        return order;
    }

    public Order shipOrder(String orderId, String trackingCode) throws OrderException {
        Order order = orderRepo.findById(orderId);
        if (order == null) {
            throw new OrderException("ORDER_NOT_FOUND", 404);
        }

        if (trackingCode == null) {
            throw new OrderException("INVALID_ORDER", 422);
        }

        if (order.status != OrderStatus.PAID) {
            throw new OrderException("OPERATION_NOT_ALLOWED", 409);
        }

        orderRepo.updateTrackingCode(orderId, trackingCode);
        orderRepo.updateStatus(orderId, OrderStatus.SHIPPED);

        order.trackingCode = trackingCode;
        order.status = OrderStatus.SHIPPED;

        Notification notification = new Notification(
            generateNotificationId(),
            NotificationType.ORDER_SHIPPED,
            orderId,
            order.cpf,
            NotificationStatus.NEW
        );
        notificationRepo.create(notification);

        return order;
    }

    public Order deliverOrder(String orderId) throws OrderException {
        Order order = orderRepo.findById(orderId);
        if (order == null) {
            throw new OrderException("ORDER_NOT_FOUND", 404);
        }

        if (order.status != OrderStatus.SHIPPED) {
            throw new OrderException("OPERATION_NOT_ALLOWED", 409);
        }

        orderRepo.updateStatus(orderId, OrderStatus.DELIVERED);
        order.status = OrderStatus.DELIVERED;

        return order;
    }

    public Order cancelOrder(String orderId) throws OrderException {
        Order order = orderRepo.findById(orderId);
        if (order == null) {
            throw new OrderException("ORDER_NOT_FOUND", 404);
        }

        if (order.status == OrderStatus.DELIVERED || order.status == OrderStatus.CANCELLED) {
            throw new OrderException("OPERATION_NOT_ALLOWED", 409);
        }

        if (order.status == OrderStatus.SHIPPED) {
            throw new OrderException("OPERATION_NOT_ALLOWED", 409);
        }

        boolean wasPaid = order.status == OrderStatus.PAID;

        orderRepo.updateStatus(orderId, OrderStatus.CANCELLED);

        if (wasPaid) {
            restoreStock(order);
            subtractCustomerCredit(order);
        }

        Notification notification = new Notification(
            generateNotificationId(),
            NotificationType.ORDER_CANCELLED,
            orderId,
            order.cpf,
            NotificationStatus.NEW
        );
        notificationRepo.create(notification);

        order.status = OrderStatus.CANCELLED;
        return order;
    }

    private void validateStockAvailability(Order order) throws OrderException {
        for (OrderItem item : order.items) {
            Product product = productRepo.findBySku(item.sku);
            if (product == null || product.stock < item.quantity) {
                orderRepo.updateStatus(order.id, OrderStatus.CANCELLED);
                Notification notification = new Notification(
                    generateNotificationId(),
                    NotificationType.ORDER_CANCELLED,
                    order.id,
                    order.cpf,
                    NotificationStatus.NEW
                );
                notificationRepo.create(notification);
                throw new OrderException("INSUFFICIENT_STOCK", 409);
            }
        }
    }

    private void deductStock(Order order) {
        for (OrderItem item : order.items) {
            productRepo.updateStock(item.sku, item.quantity);
        }
    }

    private void restoreStock(Order order) {
        for (OrderItem item : order.items) {
            productRepo.restoreStock(item.sku, item.quantity);
        }
    }

    private void addCustomerCredit(Order order) {
        customerRepo.addCredit(order.cpf, order.summary.nextPurchaseCredit);
    }

    private void subtractCustomerCredit(Order order) {
        customerRepo.subtractCredit(order.cpf, order.summary.nextPurchaseCredit);
    }

    private String generateOrderId() {
        return UUID.randomUUID().toString();
    }

    private String generateNotificationId() {
        return UUID.randomUUID().toString();
    }

    public Order findOrder(String orderId) {
        return orderRepo.findById(orderId);
    }

    public OrderRepository getOrderRepo() {
        return orderRepo;
    }
}
package com.loja.repository;

import com.loja.model.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.sql.*;
import java.time.Instant;
import java.util.*;

public class OrderRepository {
    private final Database db;
    private final ObjectMapper mapper = new ObjectMapper();

    public OrderRepository(Database db) {
        this.db = db;
    }

    public Order findById(String id) {
        String sql = "SELECT id, cpf, email, status, created_at, paid_at, tracking_code, summary_json, items_json " +
                     "FROM orders WHERE id = ?";
        try (Connection conn = db.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, id);
            try (ResultSet rs = stmt.executeQuery()) {
                if (rs.next()) {
                    return mapOrder(rs);
                }
            }
        } catch (SQLException e) {
            throw new RuntimeException("Error finding order", e);
        }
        return null;
    }

    public void create(Order order) {
        String sql = "INSERT INTO orders (id, cpf, email, status, created_at, paid_at, tracking_code, summary_json, items_json) " +
                     "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)";
        try (Connection conn = db.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, order.id);
            stmt.setString(2, order.cpf);
            stmt.setString(3, order.email);
            stmt.setString(4, order.status.name());
            stmt.setObject(5, order.createdAt);
            stmt.setObject(6, order.paidAt);
            stmt.setString(7, order.trackingCode);
            stmt.setString(8, mapper.writeValueAsString(order.summary));
            stmt.setString(9, mapper.writeValueAsString(order.items));
            stmt.executeUpdate();
        } catch (Exception e) {
            throw new RuntimeException("Error creating order", e);
        }
    }

    public void updateStatus(String id, OrderStatus status) {
        String sql = "UPDATE orders SET status = ? WHERE id = ?";
        try (Connection conn = db.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, status.name());
            stmt.setString(2, id);
            stmt.executeUpdate();
        } catch (SQLException e) {
            throw new RuntimeException("Error updating order status", e);
        }
    }

    public void updateStatusAndPaidAt(String id, OrderStatus status, Instant paidAt) {
        String sql = "UPDATE orders SET status = ?, paid_at = ? WHERE id = ?";
        try (Connection conn = db.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, status.name());
            stmt.setObject(2, paidAt);
            stmt.setString(3, id);
            stmt.executeUpdate();
        } catch (SQLException e) {
            throw new RuntimeException("Error updating order", e);
        }
    }

    public void updateTrackingCode(String id, String trackingCode) {
        String sql = "UPDATE orders SET tracking_code = ? WHERE id = ?";
        try (Connection conn = db.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, trackingCode);
            stmt.setString(2, id);
            stmt.executeUpdate();
        } catch (SQLException e) {
            throw new RuntimeException("Error updating tracking code", e);
        }
    }

    public boolean existsWithStatus(String cpf, OrderStatus status) {
        String sql = "SELECT COUNT(*) FROM orders WHERE cpf = ? AND status = ?";
        try (Connection conn = db.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, cpf);
            stmt.setString(2, status.name());
            try (ResultSet rs = stmt.executeQuery()) {
                if (rs.next()) {
                    return rs.getInt(1) > 0;
                }
            }
        } catch (SQLException e) {
            throw new RuntimeException("Error checking order status", e);
        }
        return false;
    }

    public boolean hasCompletedOrder(String cpf) {
        String sql = "SELECT COUNT(*) FROM orders WHERE cpf = ? AND status IN ('PAID', 'SHIPPED', 'DELIVERED')";
        try (Connection conn = db.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, cpf);
            try (ResultSet rs = stmt.executeQuery()) {
                if (rs.next()) {
                    return rs.getInt(1) > 0;
                }
            }
        } catch (SQLException e) {
            throw new RuntimeException("Error checking completed orders", e);
        }
        return false;
    }

    private Order mapOrder(ResultSet rs) throws SQLException {
        Order order = new Order();
        order.id = rs.getString("id");
        order.cpf = rs.getString("cpf");
        order.email = rs.getString("email");
        order.status = OrderStatus.valueOf(rs.getString("status"));
        order.createdAt = (Instant) rs.getObject("created_at", Instant.class);
        order.paidAt = (Instant) rs.getObject("paid_at", Instant.class);
        order.trackingCode = rs.getString("tracking_code");

        try {
            order.summary = mapper.readValue(rs.getString("summary_json"), OrderSummary.class);
            order.items = mapper.readValue(rs.getString("items_json"),
                mapper.getTypeFactory().constructCollectionType(List.class, OrderItem.class));
        } catch (Exception e) {
            throw new RuntimeException("Error parsing order JSON", e);
        }

        return order;
    }
}
package com.loja.repository;

import com.loja.model.Product;
import java.sql.*;

public class ProductRepository {
    private final Database db;

    public ProductRepository(Database db) {
        this.db = db;
    }

    public Product findBySku(String sku) {
        String sql = "SELECT sku, name, price, weight_kg, stock, discontinued FROM products WHERE sku = ?";
        try (Connection conn = db.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, sku);
            try (ResultSet rs = stmt.executeQuery()) {
                if (rs.next()) {
                    return new Product(
                        rs.getString("sku"),
                        rs.getString("name"),
                        rs.getDouble("price"),
                        rs.getDouble("weight_kg"),
                        rs.getInt("stock"),
                        rs.getBoolean("discontinued")
                    );
                }
            }
        } catch (SQLException e) {
